import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Mobile AI Hub: Grounded Captions, Hashtag Suggestions, Ambassadors, Ad Images, Video & Quick Reel Studio","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-ai-features/spec.md","filePath":"feature/modules/08-mobile-application/mobile-ai-features/spec.md"}'),r={name:"feature/modules/08-mobile-application/mobile-ai-features/spec.md"};function d(s,e,c,n,l,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="mobile-ai-hub-grounded-captions-hashtag-suggestions-ambassadors-ad-images-video-quick-reel-studio" tabindex="-1">Mobile AI Hub: Grounded Captions, Hashtag Suggestions, Ambassadors, Ad Images, Video &amp; Quick Reel Studio <a class="header-anchor" href="#mobile-ai-hub-grounded-captions-hashtag-suggestions-ambassadors-ad-images-video-quick-reel-studio" aria-label="Permalink to &quot;Mobile AI Hub: Grounded Captions, Hashtag Suggestions, Ambassadors, Ad Images, Video &amp; Quick Reel Studio&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>mobile-ai-features</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>08-mobile-application</code> — BrandHub Mobile Application (Expo SDK 58 / React Native 0.88)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>mobile-ai-features</code>, <code>mobile-nav-role-parity (AI Studio, Trends &amp; Quick Reel Studio)</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/README.html">3.7 AI Features</a> (<code>3.7.1–3.7.19</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Bring BrandHub&#39;s full creative AI suite to <code>brandhub-mobile-app</code> (<code>AiHubScreen.tsx</code>): <strong>AI Caption &amp; Post Studio</strong> (<code>AiCaptionScreen.tsx</code>, <code>AiPostStudioScreen.tsx</code> with Brand RAG + Neo4j Trend grounding + Contextual Hashtags), <strong>Social Trends Explorer</strong> (<code>SocialTrendsScreen.tsx</code>), <strong>Virtual Ambassador &amp; Commercial Ad Image Generators</strong> (<code>AiModelGeneratorScreen.tsx</code>, <code>AiAdImageScreen.tsx</code>), <strong>AI Product/Style Video &amp; History</strong> (<code>AiVideoScreen.tsx</code>, <code>AiVideoHistoryScreen.tsx</code>), and <strong>Quick Reel Auto-Edit Studio</strong> (<code>QuickReelStudioScreen.tsx</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, or <code>Creator</code> working on mobile, I want to browse live Brand-Fit trends, generate RAG-grounded captions and ranked hashtags, synthesize Virtual Ambassadors, commercial product images, and AI videos/Quick Reels, and save generated assets straight to the Workspace Library or device gallery.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Unified <code>X-AI-Workspace-Id</code> + <code>Idempotency-Key</code> Mobile Contract:</strong> <code>src/services/aiService.ts</code> and <code>hashtagService.ts</code> attach explicit <code>X-AI-Workspace-Id</code> and per-action <code>Idempotency-Key</code> headers matching <code>DA-974</code> / Workspace Credit Unification, invalidating credit balance queries after billable generations.</li><li><strong>AI Caption, Post Studio &amp; Hashtag Suggestions (<code>AiCaptionScreen.tsx</code>, <code>AiPostStudioScreen.tsx</code>):</strong> Generates 3-variant RAG/Trend captions, supports refine/adapt/choice, runs <code>editorModeration.ts</code> compliance checks, displays ranked hashtag provenance (<code>WORKSPACE</code>, <code>TREND_CONTEXT</code>, <code>AI_GENERATED</code>), and applies output directly to Tasks.</li><li><strong>Visual &amp; Video AI Studios (<code>AiModelGeneratorScreen.tsx</code>, <code>AiAdImageScreen.tsx</code>, <code>AiVideoScreen.tsx</code>, <code>AiVideoHistoryScreen.tsx</code>, <code>QuickReelStudioScreen.tsx</code>):</strong> Supports preset selection, gallery/camera product reference upload (<code>&lt;= 20 MB</code> normalized), resilient async job polling (<code>aiWorkerHelpers.ts</code>), native <code>expo-video</code> playback, and 1-tap save to Workspace Material Repository (<code>saveToLibrary.ts</code>) or device photo library (<code>expo-media-library</code>).</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>aiHub.*</code>, <code>aiCaption.*</code>, <code>aiImage.*</code>, <code>aiVideo.*</code>, <code>quickReel.*</code>, <code>trends.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> Parity with <code>pages/ai-studio/*</code> and <code>pages/editor/components/AI*Panel.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{AiHubScreen,AiCaptionScreen,AiPostStudioScreen,AiModelGeneratorScreen,AiAdImageScreen,AiVideoScreen,AiVideoHistoryScreen,QuickReelStudioScreen,SocialTrendsScreen}.tsx</code>, <code>src/services/{aiService,hashtagService,trendService,matchingService}.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/captions/** &amp; GET /trend-fit &amp; /credits</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>AiCaptionController</code> &lt;- <code>aiService.ts</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/content/hashtags &amp; /ambassadors/** &amp; /image/commercial/generate</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>X-AI-Workspace-Id</code></td><td style="text-align:left;"><code>AiGenerationController</code> &lt;- <code>aiService.ts</code> &amp; <code>hashtagService.ts</code></td></tr><tr><td style="text-align:left;"><code>GET/POST /api/v1/workspaces/{workspaceId}/ai/video-styles &amp; /videos/** &amp; /video-productions/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiVideoController</code> &amp; <code>ProductVideoController</code> &lt;- <code>aiService.ts</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/materials/reel-studio/auto-edit</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>MaterialController</code> &lt;- <code>QuickReelStudioScreen.tsx</code></td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong><code>Client</code> Role Exclusion:</strong> <code>Client</code> accounts cannot access AI generation screens (<code>navAccess.ts</code> + <code>withAccess.tsx</code> + backend <code>403</code>).</li><li><strong>App Backgrounded During AI Video Poll:</strong> <code>AiVideoHistoryScreen.tsx</code> resumes polling persisted <code>jobId</code> on foreground return without losing reserved credit state.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/README.html">3.7 AI Features</a> (<code>3.7.1–3.7.19</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(r,[["render",d]]);export{p as __pageData,m as default};
